package api

import "net/http"

func (s *Server) workersPage(w http.ResponseWriter, _ *http.Request) {
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	_, _ = w.Write([]byte(brandedPage(shelledPage(workersPageHTML))))
}

const workersPageHTML = `<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Timingdex · 处理节点</title><style>
:root{color-scheme:dark}*{box-sizing:border-box}body{margin:0;background:#101827;color:#edf3ff;font:15px ui-sans-serif,system-ui,-apple-system,sans-serif}header{padding:15px 6vw;border-bottom:1px solid #263651;display:flex;gap:18px;align-items:center;background:#101827ee}a{color:#b8c8ff;text-decoration:none}.brand{color:#fff;font-weight:800;margin-right:auto}.wrap{max-width:1120px;margin:auto;padding:38px 24px}.eyebrow{color:#8da7ff;font-weight:800;font-size:12px;letter-spacing:.09em}h1{font-size:clamp(30px,5vw,50px);letter-spacing:-.05em;margin:10px 0}.muted{color:#aab8d0;line-height:1.6}.grid{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-top:16px}.panel{background:#172238;border:1px solid #2c3d5b;border-radius:15px;padding:18px}.panel h2{margin:0 0 12px;font-size:18px}.node,.job{border-top:1px solid #2a3a56;padding:12px 0}.node:first-child,.job:first-child{border-top:0}.top{display:flex;justify-content:space-between;gap:10px}.name{font-weight:800}.meta{color:#aab8d0;font-size:13px;margin-top:5px;line-height:1.5}.pill{border:1px solid #465b82;border-radius:999px;padding:3px 8px;font-size:12px;color:#b8c9ff;white-space:nowrap}.online{color:#72dca6;border-color:#3c8867}.offline{color:#ffc98d;border-color:#956c3d}.compat-ok{color:#72dca6;border-color:#3c8867}.compat-warn{color:#ffd98d;border-color:#9a7b3c}.compat-bad{color:#ff9d9d;border-color:#a04a4a}.empty{color:#aab8d0;border:1px dashed #475b7a;border-radius:10px;padding:15px;font-size:13px}.auth,.assign{display:flex;gap:8px;flex-wrap:wrap}.auth input,.assign select{min-width:170px;flex:1;background:#0d1524;border:1px solid #435775;border-radius:8px;color:#fff;padding:9px}.auth button,.assign button{border:0;border-radius:8px;padding:9px 12px;background:#758fff;color:#071126;font-weight:800;cursor:pointer}.notice{font-size:13px;color:#aab8d0;margin:10px 0 0}.token{margin-top:12px;color:#ffda96;word-break:break-all;font-family:ui-monospace,monospace}.bar{height:7px;background:#0d1524;border-radius:999px;overflow:hidden;margin:8px 0}.bar i{display:block;height:100%;background:#7a93ff}.failure{color:#ffb7ac}.assign{margin-top:10px}@media(max-width:760px){.grid{grid-template-columns:1fr}.wrap{padding-top:28px}}</style></head><body data-workers-page><!--SHELL_HEADER--><main class="wrap"><div class="eyebrow">NAS HUB · WORKER FLEET</div><h1>处理节点与工作流进度</h1><p class="muted">Hub 只负责调度和保存成果；节点在自己的机器上处理挂载素材。离线节点不会丢失已上传的预览文件。</p><section class="panel"><h2>Hub 管理访问</h2><div class="auth"><button type="button" onclick="enableAdmin()">查看节点</button><button type="button" onclick="createPairing()">生成配对 Token</button></div><p class="notice">在左侧栏输入 Hub 管理 Token 后点击按钮。Token 只保留在当前页面内存中，不会写进浏览器存储；它位于 Hub 的 <code>admin-token</code> 文件。</p><div id="pairing" class="token"></div></section><div class="grid"><section class="panel"><h2>处理节点</h2><div id="workers" class="empty">请输入 Hub 管理 Token 后查看节点。</div></section><section class="panel"><h2>工作流进度</h2><div id="jobs" class="empty">请输入 Hub 管理 Token 后查看处理任务。</div></section></div></main><script>
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','>':'&gt;','<':'&lt;','"':'&quot;',"'":'&#39;'}[c]));
function node(w){const c=w.capabilities||{},online=w.status==='online',compat=w.compat||{};const caps=[c.proxy?'Proxy':'',c.thumbnail?'缩略图':'',c.audio_extract?'音频':''].filter(Boolean).join(' · ')||'只上报状态';const roots=(c.library_roots||[]).join('、')||'未挂载素材库';const hardware=(c.hardware||[]).join('、')||'软件编码（无硬件加速）';const vmap={compatible:['兼容','compat-ok'],upgrade_recommended:['建议升级','compat-warn'],incompatible:['不兼容','compat-bad']};const vp=vmap[compat.verdict]||['未知','compat-warn'];const vline='<br>版本：'+esc(compat.worker_version||'未知')+' <span class="pill '+vp[1]+'">'+vp[0]+'</span>';const vnote=(compat.verdict==='incompatible')?'<br><span class="failure">'+esc(compat.message||'该节点与本 Hub 不兼容')+'；不派发任务</span>':'';return '<article class="node"><div class="top"><span class="name">'+esc(w.name||w.id)+'</span><span class="pill '+(online?'online':'offline')+'">'+(online?'在线':'离线')+'</span></div><div class="meta">'+esc(w.platform)+' · '+esc(c.speed_class||'standard')+' · '+esc(caps)+vline+vnote+'<br>硬件加速：'+esc(hardware)+'<br>素材目录：'+esc(roots)+'<br>最后心跳：'+esc(w.last_seen_at||'尚未上报')+'</div></article>'}
let knownWorkers=[];
 function job(j){const stage=j.current_stage||'等待调度';const progress=Number.isFinite(Number(j.progress))?Number(j.progress):0;const attempt=Number.isFinite(Number(j.attempt_count))?Number(j.attempt_count):0;const maxAttempts=Number.isFinite(Number(j.max_attempts))?Number(j.max_attempts):0;const options=['<option value="">自动选择兼容节点</option>'].concat(knownWorkers.map(w=>'<option value="'+esc(w.id)+'" '+((j.assigned_worker_id===w.id||j.preferred_worker_id===w.id)?'selected':'')+'>'+esc(w.name||w.id)+'</option>')).join('');const failure=j.last_error_message?'<br><span class="failure">最近失败：'+esc(j.last_error_message)+'</span>':'';const canAssign=j.job_type==='derive';return '<article class="job"><div class="top"><span class="name">'+esc(j.job_type)+' · '+esc(j.asset_id)+'</span><span class="pill">'+esc(j.state)+'</span></div><div class="meta">'+esc(stage)+' · '+Math.round(progress)+'%<div class="bar"><i style="width:'+Math.min(100,Math.max(0,progress))+'%"></i></div>尝试 '+attempt+'/'+maxAttempts+(j.lease_owner?'<br>执行节点：'+esc(j.lease_owner):'')+failure+'</div>'+(canAssign?'<div class="assign"><select id="assignment-'+esc(j.job_id)+'">'+options+'</select><button data-action="assign" data-mode="preferred" data-job-id="'+esc(j.job_id)+'">优先</button><button data-action="assign" data-mode="required" data-job-id="'+esc(j.job_id)+'">指定</button></div>':'')+'</article>'}
let adminToken='';
function hubFetch(url,options={}){const headers=new Headers(options.headers||{});headers.set('Authorization','Bearer '+adminToken);return fetch(url,{...options,headers});}
async function apiErrMsg(r){try{const d=await r.json();if(d&&d.error&&d.error.message)return d.error.action?(d.error.message+'（'+d.error.action+'）'):d.error.message}catch(_){}return (await r.text()).trim()}
async function json(response){if(!response.ok)throw new Error(response.status===401?'管理 Token 无效或缺失':await apiErrMsg(response));return response.json();}
function enableAdmin(){adminToken=document.getElementById('admin-token').value.trim();document.getElementById('pairing').textContent='';load();}
async function createPairing(){if(!adminToken){enableAdmin();if(!adminToken)return;}try{const pairing=await hubFetch('/api/v1/hub/worker-pairings',{method:'POST'}).then(json);document.getElementById('pairing').textContent='一次性配对 Token（请立即用于 Worker enroll）：'+pairing.token;}catch(e){document.getElementById('pairing').textContent='无法生成配对 Token：'+e.message;}}
async function assignJob(id,mode){const workerID=document.getElementById('assignment-'+id).value;try{await hubFetch('/api/v1/admin/worker-jobs/'+encodeURIComponent(id)+'/assignment',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({worker_id:workerID,mode})}).then(json);load()}catch(e){alert('无法更新节点偏好：'+e.message)}}
 async function load(){if(!adminToken)return;try{const [workers,jobs]=await Promise.all([hubFetch('/api/v1/hub/workers').then(json),hubFetch('/api/v1/jobs?limit=100').then(json)]);knownWorkers=workers;const detailed=await Promise.all(jobs.map(async j=>{try{return await hubFetch('/api/v1/admin/worker-jobs/'+encodeURIComponent(j.id)).then(json)}catch(_){return j}}));document.getElementById('workers').className='';document.getElementById('workers').innerHTML=workers.length?workers.map(node).join(''):'<div class="empty">还没有配对节点。可在本页生成一次性配对 Token。</div>';document.getElementById('jobs').className='';document.getElementById('jobs').innerHTML=detailed.length?detailed.map(job).join(''):'<div class="empty">没有等待或运行中的任务。</div>'}catch(e){document.getElementById('workers').textContent='无法读取节点状态：'+e.message;document.getElementById('jobs').textContent='无法读取工作流状态。'}}document.getElementById('jobs').addEventListener('click',function(e){const b=e.target.closest('[data-action="assign"]');if(b)assignJob(b.dataset.jobId,b.dataset.mode)});setInterval(load,10000);
</script></body></html>`
